/**
 * @event
 * @name scwin.btn_openCorpCd_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openCorpCd_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openCorpCd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        open_corp_cd()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20005.btn_openCorpCd_onclick' }); }
};

